    PROCEDURE print_rc(p_name VARCHAR2, p_rc IN OUT SYS_REFCURSOR) IS
        v_cur INTEGER; v_cnt INTEGER; v_desc DBMS_SQL.DESC_TAB2; v_val VARCHAR2(4000); v_line VARCHAR2(32767); v_n PLS_INTEGER := 0;
    BEGIN
        IF p_rc IS NULL OR NOT p_rc%ISOPEN THEN DBMS_OUTPUT.PUT_LINE(p_name || ' (not open)'); RETURN; END IF;
        v_cur := DBMS_SQL.TO_CURSOR_NUMBER(p_rc);
        DBMS_SQL.DESCRIBE_COLUMNS2(v_cur, v_cnt, v_desc);
